from __future__ import annotations

"""Hydrate Action Detail evidence from App Ready before the WHY renderer runs."""

_SCRIPT=r'''<script id="yipmanV1DecisionSnapshotHydration">
(()=>{'use strict';let seq=0;const norm=v=>String(v??'').trim();const digits=v=>norm(v).replace(/\D/g,'').replace(/^0+/,'');
const identity=(body,label)=>{for(const el of body.querySelectorAll('.v1-detail-id>div')){const b=norm(el.querySelector('b')?.textContent).toUpperCase();if(b.includes(label))return norm(el.querySelector('span')?.textContent)}return''};
const actionType=body=>{const s=norm(body.querySelector('.v1-detail-decision strong')?.textContent).toUpperCase();if(s.startsWith('ORDER')||s.startsWith('NO ORDER'))return'ORDER';if(s.includes('TPR'))return'TPR';if(s.includes('REG')||s.includes('$'))return'PRICE';return''};
const value=(r,...keys)=>{for(const k of keys)if(r&&r[k]!=null&&r[k]!=='')return r[k];return null};
function add(body,key,label,val){if(val==null||val==='')return;if(body.querySelector(`[data-evidence-key="${key}"]`))return;let host=body.querySelector('.v1-detail-metrics');if(!host){host=document.createElement('div');host.className='v1-detail-metrics';body.appendChild(host)}const d=document.createElement('div');d.dataset.evidenceKey=key;d.dataset.evidenceValue=String(val);d.style.display='none';d.innerHTML='<b>'+label+'</b><span></span>';d.querySelector('span').textContent=String(val);host.appendChild(d)}
function hydrate(body,r){add(body,'EFFECTIVE OH','EFFECTIVE OH',value(r,'ordering_oh_used','effective_oh','current_oh'));add(body,'FORECAST USAGE BEFORE DELIVERY','FORECAST USAGE BEFORE DELIVERY',value(r,'forecast_usage_before_delivery','pre_delivery_usage'));add(body,'PROJECTED OH AT DELIVERY','PROJECTED OH AT DELIVERY',value(r,'projected_oh_at_delivery'));add(body,'USABLE OH AT DELIVERY','USABLE OH AT DELIVERY',value(r,'usable_oh_at_delivery'));add(body,'FORECAST COVERAGE USAGE','FORECAST COVERAGE USAGE',value(r,'forecast_coverage_usage','forecast_requested_coverage_usage','coverage_demand'));add(body,'PRE DELIVERY STOCKOUT QTY','PRE DELIVERY STOCKOUT QTY',value(r,'pre_delivery_stockout_qty'));add(body,'CURRENT PRICE','CURRENT PRICE',value(r,'current_price','observed_price'));add(body,'SUGGESTED PRICE','SUGGESTED PRICE',value(r,'suggested_price','suggested_regular_price','suggested_tpr_price'));add(body,'CURRENT COST','CURRENT COST',value(r,'current_cost','cost'));add(body,'7D SALES','7D SALES',value(r,'sales_7d','qty_7d','seven_day_sales'));add(body,'7D AVG','7D AVG',value(r,'velocity_7d','avg_daily_qty','daily_forecast'));body.dataset.appReadyDecision='1';delete body.dataset.causalDecisionEvidence;}
async function run(){const overlay=document.getElementById('v1DetailOverlay'),body=document.getElementById('v1DetailBody');if(!overlay?.classList.contains('open')||!body)return;const family=identity(body,'FAMILY'),upc=digits(identity(body,'UPC')),type=actionType(body);const sig=[family,upc,type].join('|');if(!family&&!upc||body.dataset.appReadyDecisionSig===sig)return;body.dataset.appReadyDecisionSig=sig;const mine=++seq;try{const q=new URLSearchParams();if(family)q.set('family',family);if(upc)q.set('upc',upc);if(type)q.set('action_type',type);const r=await fetch('/app/yipman-v1-rc/api/app-ready/decision?'+q,{cache:'no-store'}).then(x=>x.json());if(mine!==seq||r?.status==='SNAPSHOT_MISS'||!r?.app_ready_snapshot)return;hydrate(body,r);body.dispatchEvent(new CustomEvent('yipman-app-ready-decision-hydrated',{bubbles:true}))}catch(_){}}
let queued=false;const kick=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;run()})};new MutationObserver(kick).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});document.addEventListener('click',()=>setTimeout(kick,0),true);})();
</script>'''
def polish_decision_snapshot_hydration_html(html:str)->str:
    if 'yipmanV1DecisionSnapshotHydration' in html:return html
    return html.replace('</body>',_SCRIPT+'</body>',1)
